/* ===== v52463 viewer move runtime logging ===== */
(() => {
  'use strict';
  if (window.__v52463ViewerMoveLogging) return;
  window.__v52463ViewerMoveLogging = true;

  const MAX_ENTRIES = 250;
  const logs = window.__viewerMoveLogV52463 = window.__viewerMoveLogV52463 || [];
  let sequence = logs.length;
  let lastParent = null;
  let observer = null;

  function visiblePage() {
    if (document.getElementById('panel-3')?.classList.contains('active')) return 3;
    if (document.getElementById('panel-2')?.classList.contains('active')) return 2;
    return 0;
  }

  function snapshot(event, detail = {}) {
    const viewer = document.getElementById('comparison-modal');
    const parent = viewer?.parentElement || null;
    const shell = viewer?.closest('.review-workspace-shell-v52446') || null;
    const entry = {
      sequence: ++sequence,
      timestamp: new Date().toISOString(),
      event,
      visiblePage: visiblePage(),
      activePage: window.getReviewSideBySideStateV52447 ? undefined : null,
      viewerPresent: !!viewer,
      viewerParentId: parent?.id || '',
      viewerParentClass: parent?.className || '',
      workspaceId: shell?.id || '',
      workspacePage: shell?.dataset?.workspacePage || '',
      viewerOpen: viewer?.dataset?.open || '',
      ariaHidden: viewer?.getAttribute('aria-hidden') || '',
      display: viewer?.style?.display || getComputedStyle(viewer || document.body).display,
      page2Open: !!document.getElementById('page2-workspace-shell-v52446')?.classList.contains('is-viewer-open'),
      page3Open: !!document.getElementById('page3-workspace-shell-v52446')?.classList.contains('is-viewer-open'),
      ...detail
    };
    logs.push(entry);
    if (logs.length > MAX_ENTRIES) logs.splice(0, logs.length - MAX_ENTRIES);
    console.info('[ViewerMove v524.63]', entry);
    window.dispatchEvent(new CustomEvent('viewer-move-log-v52463', { detail: entry }));
    return entry;
  }

  function inspectParent(reason) {
    const viewer = document.getElementById('comparison-modal');
    const parent = viewer?.parentElement || null;
    if (parent !== lastParent) {
      const previousParent = lastParent;
      lastParent = parent;
      snapshot('viewer-parent-changed', {
        reason,
        fromParentId: previousParent?.id || '',
        fromParentClass: previousParent?.className || '',
        toParentId: parent?.id || '',
        toParentClass: parent?.className || ''
      });
    }
  }

  function startObserver() {
    if (observer) return;
    lastParent = document.getElementById('comparison-modal')?.parentElement || null;
    observer = new MutationObserver(records => {
      if (records.some(record => record.type === 'childList')) inspectParent('dom-mutation');
    });
    observer.observe(document.body, { childList: true, subtree: true });
    snapshot('logging-started');
  }

  document.addEventListener('click', event => {
    const target = event.target.closest?.('#comparison-side-toggle-v52446,#comparison-modal-close-v419,[data-comparison-close],#comparison-close,[data-ux-stage],#btn-back-to-panel2,#btn-back-to-panel2-top,#btn-next-panel2');
    if (!target) return;
    snapshot('viewer-control-click', {
      targetId: target.id || '',
      targetTag: target.tagName || '',
      targetStage: target.dataset?.uxStage || '',
      targetText: String(target.textContent || '').trim().replace(/\s+/g, ' ').slice(0, 120)
    });
    queueMicrotask(() => inspectParent('after-control-click'));
  }, true);

  for (const eventName of ['workflow-panel-changed', 'comparison-modal-opened', 'comparison-modal-closed']) {
    window.addEventListener(eventName, event => {
      snapshot(eventName, { eventDetail: event.detail || null });
      queueMicrotask(() => inspectParent(eventName));
      setTimeout(() => inspectParent(eventName + '-settled'), 150);
    }, true);
  }

  window.getViewerMoveLogV52463 = () => logs.map(entry => ({ ...entry }));
  window.clearViewerMoveLogV52463 = () => { logs.length = 0; sequence = 0; snapshot('log-cleared'); };
  window.exportViewerMoveLogV52463 = () => {
    const blob = new Blob([JSON.stringify(logs, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = `viewer-move-log-${new Date().toISOString().replace(/[:.]/g, '-')}.json`;
    document.body.appendChild(anchor);
    anchor.click();
    anchor.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    snapshot('log-exported', { exportedEntries: logs.length });
  };

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', startObserver, { once: true });
  else startObserver();
})();


/* ===== v52466 verify newly submitted review before restart ===== */
(() => {
  'use strict';
  if (window.__v52466VerifyNewReview) return;
  window.__v52466VerifyNewReview = true;

  const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
  const norm = value => String(value || '').trim().toLowerCase().replace(/[^a-z0-9]+/g, ' ');
  const fileName = file => String(file?.fileName || file?.['{FilenameWithExtension}'] || file?.FilenameWithExtension || file?.Name || file?.['{Name}'] || '');
  const fileDate = file => Date.parse(file?.modifiedDate || file?.Modified || file?.createdDate || file?.Created || 0) || 0;
  const filePeriod = file => String(file?.reviewPeriod || file?.period || file?.ReviewPeriod || '');

  async function verifyDataverseRecord(submission) {
    if (!submission?.id) return { ok: false, reason: 'Dataverse did not return the submitted review ID.' };
    try {
      const token = await window.getToken('https://org23279050.crm.dynamics.com/user_impersonation');
      const id = String(submission.id).replace(/[{}]/g, '');
      const response = await fetch(`${DATAVERSE_URL}/${submission.entitySet}(${id})?$select=createdon,modifiedon`, {
        headers: { Authorization: `Bearer ${token}`, Accept: 'application/json' }
      });
      if (!response.ok) return { ok: false, reason: `Dataverse returned HTTP ${response.status}.` };
      const record = await response.json();
      return { ok: true, record };
    } catch (error) {
      return { ok: false, reason: error?.message || String(error) };
    }
  }

  function verifyNewArchiveFile(submission) {
    const files = Array.isArray(window.historicalReviewState?.files) ? window.historicalReviewState.files : [];
    const submittedAt = Date.parse(submission?.submittedAt || 0) || Date.now();
    const threshold = submittedAt - 120000;
    const employeeTokens = norm(submission?.empName).split(' ').filter(Boolean);
    const expectedPeriod = norm(submission?.reviewPeriod);
    const candidates = files.filter(file => {
      const name = norm(fileName(file));
      const period = norm(filePeriod(file));
      const recent = fileDate(file) >= threshold;
      const employeeMatch = !employeeTokens.length || employeeTokens.every(token => name.includes(token) || norm(JSON.stringify(file)).includes(token));
      const periodMatch = !expectedPeriod || period === expectedPeriod || name.includes(expectedPeriod);
      return recent && employeeMatch && periodMatch;
    }).sort((a,b) => fileDate(b) - fileDate(a));
    const matchedFile = candidates[0] || null;
    return {
      ok: !!matchedFile,
      matchedFile,
      matchedFileName: matchedFile ? fileName(matchedFile) : '',
      returnedFileCount: files.length,
      reason: matchedFile ? '' : `The archive returned ${files.length} file(s), but none matched the submitted employee, review period, and submission time.`
    };
  }

  window.startNewReviewAfterArchiveV52459 = async function(button) {
    if (window.__v52466RestartPromise) return window.__v52466RestartPromise;
    const submission = { ...(window.lastSubmittedReview || {}) };
    submission.empName = submission.empName || String(document.getElementById('employee-name')?.value || '').trim();
    submission.reviewPeriod = submission.reviewPeriod || String(document.getElementById('review-period')?.value || '').trim();
    const originalHtml = button?.innerHTML || '';
    if (button) {
      button.disabled = true;
      button.setAttribute('aria-busy', 'true');
      button.innerHTML = '<i class="fas fa-circle-notch fa-spin" aria-hidden="true"></i> Verifying submitted review...';
    }

    window.__v52466RestartPromise = (async () => {
      const dataverse = await verifyDataverseRecord(submission);
      if (!dataverse.ok) throw new Error(`The new Dataverse review could not be verified: ${dataverse.reason}`);

      await sleep(8000);
      const delays = [0, 6000, 9000, 12000];
      let archive = { ok: false, reason: 'Archive verification has not run.' };
      for (let attempt = 0; attempt < delays.length; attempt++) {
        if (delays[attempt]) await sleep(delays[attempt]);
        if (button) button.innerHTML = `<i class="fas fa-circle-notch fa-spin" aria-hidden="true"></i> Verifying new review ${attempt + 1}/${delays.length}...`;
        await window.fetchSharePointHistory(submission.empName);
        archive = verifyNewArchiveFile(submission);
        console.info('[NewReviewVerification v524.66]', { attempt: attempt + 1, submission, dataverseVerified: dataverse.ok, ...archive });
        if (archive.ok) break;
      }

      if (!archive.ok) {
        throw new Error(`The review exists in Dataverse, but the newly generated archive document was not verified after 4 checks. ${archive.reason}`);
      }

      const result = {
        employeeName: submission.empName,
        submittedReviewId: submission.id || '',
        submittedAt: submission.submittedAt || '',
        reviewPeriod: submission.reviewPeriod || '',
        dataverseVerified: true,
        archiveVerified: true,
        matchedArchiveFile: archive.matchedFileName,
        checkedAt: new Date().toISOString()
      };
      try { sessionStorage.setItem('performanceReview.lastArchiveRestart.v52466', JSON.stringify(result)); } catch (_) {}
      if (button) button.innerHTML = '<i class="fas fa-check" aria-hidden="true"></i> New review verified. Starting fresh...';
      await sleep(650);
      window.location.reload();
    })();

    try { return await window.__v52466RestartPromise; }
    catch (error) {
      window.__v52466RestartPromise = null;
      console.error('[NewReviewVerification v524.66] Restart blocked:', error);
      if (button) {
        button.disabled = false;
        button.removeAttribute('aria-busy');
        button.innerHTML = originalHtml;
      }
      if (typeof window.showError === 'function') window.showError(error.message || String(error));
      else alert(error.message || String(error));
      throw error;
    }
  };
})();


/* ===== v52467 durable comparison close authority ===== */
(() => {
  'use strict';
  if (window.__v52467DurableComparisonClose) return;
  window.__v52467DurableComparisonClose = true;

  function hardClose(reason = 'unknown') {
    const viewer = document.getElementById('comparison-modal');
    const page = document.getElementById('panel-3')?.classList.contains('active') ? 3 : 2;

    // First update the v52447 controller's private open state through its public API.
    try { window.closeReviewSideBySideV52447?.(page); } catch (error) {
      console.warn('[ComparisonClose v524.67] Controller close failed; applying DOM fallback.', error);
    }

    // Then enforce the resulting DOM state so no later legacy controller can leave the pane visible.
    document.querySelectorAll('.review-workspace-shell-v52446').forEach(shell => shell.classList.remove('is-viewer-open'));
    if (viewer) {
      viewer.dataset.open = 'false';
      viewer.setAttribute('aria-hidden', 'true');
      viewer.classList.remove('comparison-side-pane-v52446');
      viewer.style.setProperty('display', 'none', 'important');
      viewer.style.setProperty('visibility', 'hidden', 'important');
      viewer.style.removeProperty('width');
      viewer.style.removeProperty('height');
      if (viewer.parentElement !== document.body) document.body.appendChild(viewer);
    }

    window.dispatchEvent(new CustomEvent('comparison-modal-closed-v52467', { detail: { page, reason } }));
    console.info('[ComparisonClose v524.67]', {
      page,
      reason,
      viewerHidden: !viewer || getComputedStyle(viewer).display === 'none',
      page2Open: !!document.getElementById('page2-workspace-shell-v52446')?.classList.contains('is-viewer-open'),
      page3Open: !!document.getElementById('page3-workspace-shell-v52446')?.classList.contains('is-viewer-open')
    });
    return false;
  }

  function bindCloseButton() {
    const button = document.getElementById('comparison-modal-close-v419');
    if (!button || button.dataset.v52467Bound === 'true') return;
    button.dataset.v52467Bound = 'true';
    button.type = 'button';
    button.setAttribute('aria-label', 'Close side-by-side review');
    button.onclick = event => {
      event?.preventDefault?.();
      event?.stopPropagation?.();
      return hardClose('direct-button-handler');
    };
    button.addEventListener('pointerup', event => {
      if (event.pointerType === 'touch') {
        event.preventDefault();
        hardClose('touch-pointer-handler');
      }
    });
  }

  // Rebind after the shared viewer moves between Page 2 and Page 3.
  const observer = new MutationObserver(bindCloseButton);
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
      bindCloseButton();
      observer.observe(document.body, { childList: true, subtree: true });
    }, { once: true });
  } else {
    bindCloseButton();
    observer.observe(document.body, { childList: true, subtree: true });
  }

  // Keyboard fallback keeps Escape functional regardless of the active page.
  document.addEventListener('keydown', event => {
    if (event.key !== 'Escape') return;
    const viewer = document.getElementById('comparison-modal');
    if (viewer?.dataset.open === 'true' || viewer?.getAttribute('aria-hidden') === 'false') hardClose('escape-key');
  }, true);

  window.closeComparisonV52467 = hardClose;
})();


